def load_frames(vid):
    lv = LEVEL[vid]; dur = lv['dur']; fr_full = []; fr_crop = []
    arr = np.array(Image.open(f"sb/{vid}_L0_default.jpg").convert('RGB')).astype(float)
    ch = 27
    cy = None
    if lv['crop']:
        # scale crop to 27px tile: fraction of 180
        f0, f1 = lv['crop'][0]/180.0, lv['crop'][1]/180.0
        cy = (int(round(f0*ch)), int(round(f1*ch)))
    for i in range(10):
        for j in range(10):
            t = (i*10+j+0.5)*dur/100.0
            tile = arr[i*27:(i+1)*27, j*48:(j+1)*48]
            fr_full.append((t, dec(tile).mean()))
            if cy: fr_crop.append((t, dec(tile[cy[0]:cy[1]]).mean()))
            else: fr_crop.append((t, dec(tile).mean()))
    for s in range((lv['count']+lv['cols']*lv['rows']-1)//(lv['cols']*lv['rows'])):
        arr = np.array(Image.open(f"sb/{vid}_L{lv['level']}_M{s}.jpg").convert('RGB')).astype(float)
        H,W = arr.shape[:2]; th,tw = H//lv['rows'], W//lv['cols']
        c0, c1 = (None, None)
        if lv['crop']:
            c0 = int(round(lv['crop'][0]/180.0*th)); c1 = int(round(lv['crop'][1]/180.0*th))
        for i in range(lv['rows']):
            for j in range(lv['cols']):
                idx = s*lv['cols']*lv['rows'] + i*lv['cols'] + j
                if idx >= lv['count']: break
                tt = idx*lv['interval'] + lv['interval']/2.0
                tile = arr[i*th:(i+1)*th, j*tw:(j+1)*tw]
                fr_full.append((tt, dec(tile).mean()))
                fr_crop.append((tt, dec(tile[c0:c1]).mean()) if c0 is not None else (tt, dec(tile).mean()))
    def prep(fr):
        fr.sort(key=lambda x:x[0])
        tt=[fr[0]]
        for x in fr[1:]:
            if x[0]-tt[-1][0] > 0.2: tt.append(x)
        return np.array([x[0] for x in tt]), np.array([x[1] for x in tt])
    return prep(fr_full), prep(fr_crop)

def step_profile(t, v, w0, w1):
    n = len(t); mids = np.empty(n+1)
    mids[0] = t[0] - (t[1]-t[0])/2; mids[n] = t[-1] + (t[-1]-t[-2])/2
    mids[1:n] = (t[:-1]+t[1:])/2
    est = np.zeros(len(w0))
    for i in range(len(w0)):
        a,b = w0[i], w1[i]
        lo = np.maximum(mids[:-1], a); hi = np.minimum(mids[1:], b)
        wgt = np.clip(hi-lo, 0, None); W = wgt.sum()
        est[i] = enc255((wgt*v).sum()/W) if W>0 else np.nan
    return est

def spearman(x,y):
    return np.corrcoef(np.argsort(np.argsort(x)), np.argsort(np.argsort(y)))[0,1]

